node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Order ORD-5B048F details
const order2 = db.prepare(\"SELECT * FROM orders WHERE order_id = 'ORD-5B048F'\").all();
console.log('=== ORDER ORD-5B048F ===');
console.log(JSON.stringify(order2, null, 2));

const items2 = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-5B048F'\").all();
console.log('=== ORDER ITEMS ORD-5B048F ===');
console.log(JSON.stringify(items2, null, 2));

// Find the Anker speaker product
const speaker = db.prepare(\"SELECT * FROM products WHERE name LIKE '%Anker%Bluetooth%Speaker%'\").all();
console.log('=== ANKER SPEAKER PRODUCT ===');
console.log(JSON.stringify(speaker, null, 2));

// Check warranties table for this order
const warranties = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-5B048F'\").all();
console.log('=== WARRANTIES ORD-5B048F ===');
console.log(JSON.stringify(warranties, null, 2));

// Also check warranties by product id
const speakerProductId = speaker.length > 0 ? speaker[0].product_id : '';
if (speakerProductId) {
  const warByProduct = db.prepare(\"SELECT * FROM warranties WHERE product_id = ?\").all(speakerProductId);
  console.log('=== WARRANTIES BY PRODUCT ===');
  console.log(JSON.stringify(warByProduct, null, 2));
}
"
